{
  "status": "STABLE",
  "core_findings": [
    "Item embedding similarity scores of 0.5062–0.5202 correspond to mean cosine similarities near zero, providing no evidence of broad directional collapse.",
    "Training-position separation is strongest for CDs_and_Vinyl and weakest for Industrial_and_Scientific, where negatives outrank positives in 8.04% of cases and 11.99% have margins below 0.5."
  ],
  "key_implications": [
    "The model ranks positives above sampled negatives at most measured training positions across all four datasets.",
    "Strong training separation, especially for CDs_and_Vinyl, does not establish validation ranking quality or rule out overfitting."
  ],
  "evidence": {
    "headline_metrics": {
      "Electronics:embedding_collapse_score": 0.5202,
      "Industrial_and_Scientific:pos_neg_margin_p10": 0.2551,
      "Industrial_and_Scientific:pos_neg_neg_beats_pos_rate": 0.0804,
      "CDs_and_Vinyl:pos_neg_margin_p10": 4.8543,
      "CDs_and_Vinyl:pos_neg_neg_beats_pos_rate": 0.0088
    },
    "brief_metric_read": {
      "Electronics:embedding_collapse_score": "Highest similarity score, still near the zero-cosine midpoint.",
      "Industrial_and_Scientific:pos_neg_margin_p10": "Weakest lower-tail separation.",
      "Industrial_and_Scientific:pos_neg_neg_beats_pos_rate": "Highest sampled-negative outranking rate.",
      "CDs_and_Vinyl:pos_neg_margin_p10": "Strong separation even at the tenth percentile.",
      "CDs_and_Vinyl:pos_neg_neg_beats_pos_rate": "Only 0.88% of sampled negatives outrank positives."
    }
  }
}
